	FY[9] = (Z[52]-Z[23])*Z[0];
	FY[10] = 1.*(Z[53]-Z[33]-Z[1])*Z[0];
	FY[11] = (Z[54]-Z[43])*Z[0];
	FX[2] = Z[55]*Z[0];
	Z[0] = 1.0/Y[67];
	Y[8] = 1.*(Y[22]-Y[3])*Z[0];
	Z[56] = -Z[0];
	Z[57] = Y[20]*Z[0];
	YP[1] = Y[15]*Z[5];
	FY[4] = Z[15]*Z[5];
