static real_T *GetUpdatedWork(SimStruct *S, int_T getnofeed)
{
	int_T j,flag;

	real_T *w = ssGetRWork(S);
	real_T t = ssGetT(S);
	real_T *x = ssGetDiscStates(S);
	InputRealPtrsType i;
	InputRealPtrsType p = ssGetInputPortRealSignalPtrs(S,1);

	flag=0;
	if( fabs(w[0]-t)>1e-6*TIMESTEP ) flag=1;
	w[0]=t;
	for(j=0;j<NDIFF;j++) if( w[j+1]!=x[j] ) { flag=1; w[j+1]=x[j]; }
	i = ssGetInputPortRealSignalPtrs(S,2);
	for(j=0;j<NINP;j++) if( w[j+NDIFF+NIX1-NINP+1]!=i[j][0] ) { flag=1; w[j+NDIFF+NIX1-NINP+1]=i[j][0]; }
	for(j=0;j<NPAR;j++) if( w[j+NEQ+1]!=p[j][0] ) { flag=1; w[j+NEQ+1]=p[j][0]; }
	if(flag) numdiffinp(w,0);

	if(flag) {
		fp(NEQ,w[0],&w[1],&w[NEQ+NPAR+1]);
		if( IS_UNDEF(w[NEQ+NPAR+1]) ) {
			if( NDIFF>0 && ssIsVariableStepSolver(S) )
				for(j=1;j<NDIFF;j++) w[NEQ+NPAR+1+j] = w[NEQ+NPAR+1];
			else
			{
				ssSetErrorStatus(S,"index-1 and derivative evaluation failure");
				if (fptr) {
					writeErrorToFile(fptr,ssGetErrorStatus(S));
					fptr = NULL;				}
			}
		}
	}

	return(w);
}

static void StepWithEvents(SimStruct *S)
{
	real_T *ws0,*ws1,*y,*yp,*ypre,*zc,*y0,*yp0,*zc0,*w=ssGetRWork(S);
	real_T t0,tf,h,vl,vr,ept,cpt,vle,vre,hrel,qa,qb;
	int_T *modes=ssGetIWork(S),*oldmodes,*inc,*req;
	int_T iter,i,flag,evt;
	InputRealPtrsType in=ssGetInputPortRealSignalPtrs(S,2);
	real_T tol,delta,ft[NDFA],fy[NDFA*NDFA],ft0[NDFA],fy0[NDFA*NDFA];
	M_INT ip[NDFA],j;
#ifdef MIDSTEPEVENTDEBUG
	int_T gottime;
#endif

	/* Allocate memory for both vectors and split it up */
	if( (ws0=(real_T *)malloc(2*(1+2*NEQ+NPAR+NDFA+NEVT)*sizeof(double)))==NULL )
		ssSetErrorStatus(S,"unable to allocate memory");

	ws1=&ws0[1+2*NEQ+NPAR+NDFA+NEVT];

	/* Setup pointers into current and backup w vectors */
	y=&w[1]; yp=&y[NEQ+NPAR]; ypre=&yp[NDFA]; zc=&ypre[NEQ];
	y0=&ws0[1]; yp0=&y0[NEQ+NPAR]; zc0=&yp0[NDFA+NEQ];
	oldmodes=&modes[NZC]; inc=&oldmodes[NZC]; req=&inc[NEVT];

	tf=w[0]+TIMESTEP;
	/* Evaluate triggers at start of interval */
	eev(w[0],y,y,zc);
	for(iter=0;;iter++) {
#ifdef MIDSTEPEVENTDEBUG
		gottime=0;
#endif
		/* Back up all values into backup w vector */
		t0=w[0];
		for(i=0;i<1+2*NEQ+NPAR+NDFA+NEVT;i++) ws0[i]=w[i];
		/* Set step size and new time */
		h=tf-t0;
		w[0]=tf;
		/* Take Implicit Euler step */
		Dfp(t0,y,ft0,fy0);
		for(i=0;i<NDIFF;i++) {
			for(j=0;j<NDIFF;j++) fy[i*NDIFF+j]=-fy0[i*NDIFF+j];
			fy[i*(NDIFF+1)]+=1.0/h;
			ft[i]=yp[i]+h*ft0[i];
		}
		DecompCInc(NDIFF,fy,NDIFF,ip);
		SolveCInc(NDIFF,fy,NDIFF,ip,ft);
		for(i=0;i<NDIFF;i++) y[i]+=ft[i];
		/* Update: populate the inputs */
		for(i=0;i<NINP;i++) w[NDIFF+NIX1-NINP+1+i]=in[i][0];
		/* Compute the new fp */
		fp(NEQ,w[0],y,yp);
		if( IS_UNDEF(yp[0]) ) {
			ssSetErrorStatus(S,"index-1 and derivative evaluation failure");
			w[0]=tf;
			free(ws0);
			return;
		}

		/* Early termination for no internal events in step */
		if( MAXEVENTPERSTEP==0 ) break;
		/* Check iteration limit */
		if(iter==MAXEVENTPERSTEP) break;

		/* Compute zero crossings at end of step */
		eev(tf,y,y,zc);

		/* Back up all values */
		for(i=0;i<1+2*NEQ+NPAR+NDFA+NEVT;i++) ws1[i]=w[i];

		/* Find event */
		evt=-1;
		ept=tf;
		vle=tf;
		vre=tf;
		for(i=0;i<NEVT;i++) {
			flag=0;
#ifdef EVTHYST
			if( zc[i]>EVTHYST && modes[2*i]==0 && (!req[i] || y[req[i]-1]==0.0)) {
				vl=zc0[i]-EVTHYST; vr=zc[i]-EVTHYST; flag=1;
#ifdef MIDSTEPEVENTDEBUG
				if(!gottime && !iter) printf("\n");
				if(!gottime) printf("###%li### Checking interval %e..%e\n",iter+1,t0,tf); gottime=1;
				if(vl*vr>0.0)
					printf("Event %li +hyst: left=%e, right=%e, diff=%e #######\n",i,vl,vr,vl-vr);
				else
					printf("Event %li +hyst: left=%e, right=%e, diff=%e\n",i,vl,vr,vl-vr);
#endif
			}
			else if( zc[i]<-EVTHYST && modes[2*i+1]==1 && !inc[i]
				&& (!req[i] || y[req[i]-1]==1.0)) {
#ifdef MIDSTEPEVENTDEBUG
				if(!gottime && !iter) printf("\n");
				if(!gottime) printf("###%li### Checking interval %e..%e\n",iter+1,t0,tf); gottime=1;
				if(vl*vr>0.0)
					printf("Event %li -hyst: left=%e, right=%e, diff=%e #######\n",i,vl,vr,vl-vr);
				else
					printf("Event %li -hyst: left=%e, right=%e, diff=%e\n",i,vl,vr,vl-vr);
#endif
				vl=zc0[i]+EVTHYST; vr=zc[i]+EVTHYST; flag=1;
			}
#else
			if( (zc[i]>0.0 && modes[i]==0 && !req[i] || y[req[i]-1]==0.0) ||
				( zc[i]<0.0 && modes[i]==1 && !inc[i]
					&& (!req[i] || y[req[i]-1]==1.0)) ) {
#ifdef MIDSTEPEVENTDEBUG
				if(!gottime && !iter) printf("\n");
				if(!gottime) printf("###%li### Checking interval %e..%e\n",iter+1,t0,tf); gottime=1;
				if(vl*vr>0.0)
					printf("Event %li: left=%e, right=%e, diff=%e #######\n",i,vl,vr,vl-vr);
				else
					printf("Event %li: left=%e, right=%e, diff=%e\n",i,vl,vr,vl-vr);
#endif
				vl=zc0[i]; vr=zc[i]; flag=1;
			}
#endif
			if(flag) {
				/* Find zero crossing using linear approx */
				if(vl*vr>0.0) vl=0.0;
				cpt = vl/(vl-vr);
				if(cpt<0.0) cpt=t0;
				if(cpt>1.0) cpt=tf;
				else cpt=t0+h*cpt;
				/* Only take earliest */
				if( cpt<ept ) {
					ept=cpt;
					evt=i;
					vle=vl; vre=vr;
				}
			}
		}

		/* Check if we are done: no events or event very close to end
			of step - note we need to add a 'bit' to make sure the event
			will trigger */
		ept+=SHORTEVENTRATIO*TIMESTEP;
		if( evt<0 || ept>=tf ) break;
#ifdef MIDSTEPEVENTDEBUG
		printf("Have event %li in interval %e..%e at %e\n",evt,t0,tf,ept);
		printf("Trigger values: %e..%e\n",vle,vre);
#endif

		/* Step to where we suspect the event is, and check */
		h=ept-t0;
		w[0]=t0+h;
		/* Take Implicit Euler step */
		for(i=0;i<NDIFF;i++) {
			for(j=0;j<NDIFF;j++) fy[i*NDIFF+j]=-fy0[i*NDIFF+j];
			fy[i*(NDIFF+1)]+=1.0/h;
			ft[i]=yp0[i]+h*ft0[i];
		}
		DecompCInc(NDIFF,fy,NDIFF,ip);
		SolveCInc(NDIFF,fy,NDIFF,ip,ft);
		for(i=0;i<NDIFF;i++) y[i]=y0[i]+ft[i];
		/* Interpolate inputs */
		vr=h/(tf-t0);
		for(i=NDIFF+NIX1-NINP;i<NDIFF+NIX1;i++) y[i]=y0[i]+vr*(y[i]-y0[i]);
		/* Re-evaluate index-1 and derivatives */
		fp(NEQ,w[0],y,yp);
		if( IS_UNDEF(yp[0]) ) {
			ssSetErrorStatus(S,"index-1 and derivative evaluation failure");
			w[0]=tf;
			free(ws0);
			return;
		}
		eev(w[0],y,y,zc);
#ifdef EVTHYST
		if( vre>0.0 && modes[2*evt]==0 )
			cpt=zc[evt]-EVTHYST;
		else if( vre<0.0 && modes[2*evt+1]==1 )
			cpt=zc[evt]+EVTHYST;
#else
		cpt=zc[evt];
#endif
#ifdef MIDSTEPEVENTDEBUG
		printf("Value at event (t=%e) is %e\n",w[0],cpt);
#endif
		if( cpt*vre<0.0 ) {
			/* Failed, just restore w and give up ... */
#ifdef MIDSTEPEVENTDEBUG
			printf("############Event root failure in step t=%e..%e\n",t0,tf);
#endif
			for(i=0;i<1+2*NEQ+NPAR+NDFA+NEVT;i++) w[i]=ws1[i];
			break;
		}
		/* Run events */
		if(RunEvents(S,w,modes,0,23,EVTITER)) {
			w[0]=tf;
			free(ws0);
			return;
		}
	}
	free(ws0);
	RunEvents(S,w,modes,0,23,EVTITER);
}

#define MDL_UPDATE
static void mdlUpdate(SimStruct *S, int_T tid)
{
	real_T *w=ssGetRWork(S), *x = ssGetDiscStates(S);
	int_T i;

	UNUSED_ARG(tid);

	for(i=0;i<NDIFF;i++) x[i]=w[i+1]+TIMESTEP*w[NEQ+NPAR+1+i];
}

static void mdlOutputs(SimStruct *S, int_T tid)
{
	real_T *w, *y = ssGetOutputPortRealSignal(S,0);
	int_T *iw = ssGetIWork(S);
	int_T i;
	real_T *x;
	InputRealPtrsType p;

	UNUSED_ARG(tid);

	if(!iw[INIDREF]) {
		InitializeConditions(S);
		iw[INIDREF]=1;
	}
	if( ssIsVariableStepSolver(S) ) {
		ssSetErrorStatus(S,"code generated for fixed step, cannot be used with variable step");
		if (fptr) {
			writeErrorToFile(fptr,ssGetErrorStatus(S));
			fptr = NULL;
		}
		return;
	}
	if( !iw[DODERREF] ) {
		w=GetUpdatedWork(S,0);
		iw=ssGetIWork(S);
		if(RunEvents(S,w,iw,0,23,EVTITER)) return;
		if(MAXEVENTPERSTEP>0) iw[DODERREF]=1;
	}
	else {
		w=ssGetRWork(S);
		p = ssGetInputPortRealSignalPtrs(S,1);
		for(i=0;i<NPAR;i++) w[1+NEQ+i]=p[i][0];
		StepWithEvents(S);
	}
	x=ssGetDiscStates(S);
	for(i=0;i<NDIFF;i++) x[i]=w[i+1];
	otp(w[0],&w[1],&w[NEQ+NPAR+1]);
	y[ 0]=w[15];
	y[ 1]=w[19];
	y[ 2]=w[16];
	y[ 3]=w[18];
	y[ 4]=w[10];
	y[ 5]=w[11];
	y[ 6]=w[12];
	y[ 7]=w[ 3];
 	if ( fptr && ssIsMajorTimeStep(S) )
		if ( w[0]>=(lastsampletime+minsamplestep)*(1-1e-15) ) {
			fwrite(w,sizeof(real_T),NEQ+1,fptr);
			lastsampletime=w[0];
			if ( numpts++ == WARNNUMDATPTS )
				ssPrintf("Warning: At time t=%.16g, %d data points were written into file %s; consider increasing the minimum sample step, %.16g, to limit file size.\n",
						w[0],WARNNUMDATPTS,fstr,minsamplestep);
		}
}

static void mdlTerminate(SimStruct *S) {
	if (fptr) {
		fclose(fptr);
		fptr = NULL;
	}
}

